<?php

declare(strict_types=1);namespace App\Services\Subjects;use App\Models\{AcademicYear,Subject,User};use App\Services\Exports\DatabaseXlsxService;use Symfony\Component\HttpFoundation\BinaryFileResponse;
class SubjectExportService {public function __construct(private DatabaseXlsxService $xlsx){}public function download(User $actor):BinaryFileResponse{$year=AcademicYear::where('is_active',true)->value('name')??'tanpa-tahun-ajaran';$subjects=[['Kode','Mata Pelajaran','Kategori']];$loads=[['Kode','Mata Pelajaran','Tingkat','Program','JP per Minggu']];foreach(Subject::with('gradeLoads.gradeLevel')->orderBy('sort_order')->get() as $subject){$subjects[]=[$subject->code,$subject->name,$subject->category];foreach($subject->gradeLoads as $load)$loads[]=[$subject->code,$subject->name,$load->gradeLevel->roman_label,$load->program_type->label(),$load->weekly_hours];}$path=tempnam(sys_get_temp_dir(),'subjects').'.xlsx';$this->xlsx->write(['Mata Pelajaran'=>$subjects,'Struktur JP'=>$loads],$path);activity('mata-pelajaran')->causedBy($actor)->log('Mengekspor Mata Pelajaran dan Struktur JP.');return response()->download($path,'mata-pelajaran-struktur-jp-'.str_replace(['/',' '],'-',$year).'.xlsx')->deleteFileAfterSend(true);}}
